static struct snd_sf_sample * set_sample ( struct snd_soundfont * sf , struct soundfont_voice_info * avp ) { struct snd_sf_sample * sample ; sample = find_sample ( sf , avp -> sample ) ; avp -> start += sample -> v . start ; avp -> end += sample -> v . end ; avp -> loopstart += sample -> v . loopstart ; avp -> loopend += sample -> v . loopend ; avp -> sample_mode = sample -> v . mode_flags ; return sample ; } 